    """Oxirgi 120 kunlik "saytga kirgan kunlar"ni mavjud izlardan tiklaydi.

    Manbalar: muvaffaqiyatli loginlar, sessiyalar, körilgan videolar, vazifalar,
    testlar va quiz urinişlari. Har (öquvçi, kun) uçun eng erta va eng keç vaqt olinadi.
    """
    User = apps.get_model('accounts', 'CustomUser')
    Visit = apps.get_model('accounts', 'StudentDailyVisit')
    since = timezone.now() - timedelta(days=BACKFILL_DAYS)
    students = dict(User.objects.filter(role='student').values_list('username', 'id'))
    student_ids = set(students.values())
    seen = {}

    def add(uid, dt):
        if uid not in student_ids or dt is None:
            return
        local = timezone.localtime(dt) if timezone.is_aware(dt) else dt
        key = (uid, local.date())
        first, last = seen.get(key, (dt, dt))
        seen[key] = (min(first, dt), max(last, dt))

    sources = [
        (apps.get_model('accounts', 'UserSession'), 'user_id', 'started_at'),
        (apps.get_model('accounts', 'VideoProgress'), 'user_id', 'watched_at'),
        (apps.get_model('accounts', 'HomeworkSubmission'), 'student_id', 'submitted_at'),
        (apps.get_model('accounts', 'TestResult'), 'student_id', 'completed_at'),
        (apps.get_model('accounts', 'SpeakingSubmission'), 'student_id', 'submitted_at'),
        (apps.get_model('quiz', 'Attempt'), 'student_id', 'started_at'),
    ]
    for model, user_field, time_field in sources:
        for uid, dt in model.objects.filter(**{f'{time_field}__gte': since}).values_list(user_field, time_field).iterator():
            add(uid, dt)
    LoginAttempt = apps.get_model('accounts', 'LoginAttempt')
    for username, dt in LoginAttempt.objects.filter(was_successful=True, attempted_at__gte=since) \
            .values_list('username', 'attempted_at').iterator():
        add(students.get(username), dt)

    Visit.objects.bulk_create(
        [Visit(user_id=uid, date=day, first_seen=first, last_seen=last) for (uid, day), (first, last) in seen.items()],
        batch_size=1000, ignore_conflicts=True,
    )


